function inboundMarkers(owner){const entries=DRAFTS?.list(owner,'inbound-operation')||[],byId=new Map();for(const entry of entries){const marker=entry.payload;if(marker?.operationId)byId.set(marker.operationId,marker);else if(entry.entity==='pending'&&marker)byId.set('legacy',marker);}return [...byId.values()];}
