async function inboundCheck(){if(!inboundReady()||!inboundTask?.uncertain||inboundTask.busy||inboundTask.verified)return;const owner=draftAcct();return inboundLock(owner,async coordinated=>{if(!inboundReady()||!inboundTask?.uncertain||inboundTask.busy||inboundTask.verified)return;const task=inboundTask,identitySafe=editorContext(),marker=task.marker||inboundMarker(owner),safe=()=>identitySafe()&&inboundOwns(owner,marker);task.busy=true;task.checking=true;render();try{if(!safe())throw Error('原操作保護識別已變更，保留其他操作的紀錄，沒有清除或重送。');if(!await store.verifyInboundPlan(marker?.plan,safe))throw Error('尚未讀到全部預期寫入，可能仍在處理或只有部分完成。原輸入保留，不會重送。');if(!safe())throw Error('帳號或原操作已變更，沒有套用查核結果');if(coordinated)inboundDiscard(owner,marker);const kind={batch:'inbound-batch',receipt:'recv-serial',confirm:'inbound-confirm'}[marker.kind];if(coordinated&&kind)DRAFTS?.discard(owner,kind,marker.kind==='batch'?'new':marker.id);task.verified=true;task.verifiedResult=true;task.error='已讀回核對這次的全部寫入，沒有重送。本頁清單尚未更新，已暫時隱藏舊進度與輸入表單，避免誤讀。可重新整理或另開分頁查看正式結果；本頁不再送出入庫。'+(!coordinated?' 目前瀏覽器僅能只讀核對，保護識別與原輸入仍保留；請用支援分頁協調的新版瀏覽器完成核對。':'');}catch(e){task.error=String(e?.message||e);}finally{task.busy=false;task.checking=false;render();}},true);}
